#!/usr/bin/env node
// Preview all 6 email templates — sends to a single recipient via Resend.
// Usage:
//   cd web && node scripts/send-email-previews.mjs <recipient-email>
// Reads RESEND_API_KEY from .env.vercel-prod-temp or process.env.

import { readFileSync, existsSync } from 'node:fs'
import { Resend } from 'resend'

// ———————————————————————————————————————————————————————————————
// 1. Locate API key
// ———————————————————————————————————————————————————————————————
function loadEnvFromFile(path) {
  if (!existsSync(path)) return
  const txt = readFileSync(path, 'utf8')
  for (const line of txt.split(/\r?\n/)) {
    const m = line.match(/^([A-Z_][A-Z0-9_]*)=(?:"(.*)"|(.*))$/i)
    if (m && !process.env[m[1]]) process.env[m[1]] = m[2] ?? m[3] ?? ''
  }
}
loadEnvFromFile('.env.vercel-prod-temp')
loadEnvFromFile('.env.production')
loadEnvFromFile('.env.local')

const apiKey = process.env.RESEND_API_KEY
if (!apiKey) {
  console.error('RESEND_API_KEY not set')
  process.exit(1)
}

const recipient = process.argv[2]
if (!recipient || !recipient.includes('@')) {
  console.error('Usage: node scripts/send-email-previews.mjs <recipient-email>')
  process.exit(1)
}

const FROM = process.env.DIGEST_FROM_EMAIL || 'Projetus <noreply@projetus.org>'
const LOGIN_URL = 'https://projetus.vercel.app/login'
const PROPOSTA_URL = 'https://projetus.vercel.app/tgov?nr=123456%2F2025'

// ———————————————————————————————————————————————————————————————
// 2. Inline the template builders (ESM cannot import .ts directly)
//    Keep in sync with web/src/lib/email-templates.ts
// ———————————————————————————————————————————————————————————————
const BRAND = "#0072F7"
const BRAND_MAGENTA = "#FD225C"
const BRAND_PURPLE = "#7A4BAC"
const LOGO = "data:image/png;base64,"
const TEXT_DARK = '#1E293B'
const TEXT_BODY = '#374151'
const TEXT_MUTED = '#6B7280'
const TEXT_FAINT = '#9CA3AF'
const BORDER = '#E5E7EB'
const BG_PAGE = '#F8FAFC'
const BG_CARD = '#FFFFFF'
const BG_SUBTLE = '#F9FAFB'
const FONT_HEADING = `'Space Grotesk', 'Segoe UI', Helvetica, Arial, sans-serif`
const FONT_BODY = `'Inter', 'Segoe UI', Helvetica, Arial, sans-serif`

function escapeHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;')
}

function baseLayout(title, bodyHtml) {
  return `<!DOCTYPE html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
</head>
<body style="margin:0;padding:0;background:${BG_PAGE};font-family:${FONT_BODY};color:${TEXT_DARK};-webkit-font-smoothing:antialiased;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${BG_PAGE};padding:40px 16px;"><tr><td align="center">
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="background:${BG_CARD};border-radius:16px;overflow:hidden;max-width:560px;border:1px solid ${BORDER};">
<tr><td style="height:4px;background:linear-gradient(90deg, ${BRAND_MAGENTA} 0%, ${BRAND_PURPLE} 50%, ${BRAND} 100%);font-size:0;line-height:0;">&nbsp;</td></tr>
<tr><td style="padding:36px 40px 20px;text-align:center;">
<img src="${LOGO}" alt="Projete" width="180" style="display:inline-block;width:180px;height:auto;max-width:180px;">
<div style="font-family:${FONT_BODY};font-size:12px;color:${TEXT_FAINT};margin-top:10px;font-weight:400;letter-spacing:0.2px;">CRM &amp; TGov</div>
<div style="font-family:${FONT_BODY};font-size:10px;color:${BRAND};margin-top:8px;letter-spacing:0.3px;"><img src="https://bterminal.io/bt-mark.png" alt="BTerminal Systems" width="16" height="16" style="display:inline-block;vertical-align:middle;margin-right:5px;"><a href="https://bterminal.io" style="color:${BRAND};text-decoration:none;">Powered by <strong style="font-weight:600;">BTerminal Systems</strong></a></div>
</td></tr>
<tr><td style="padding:0 40px;"><div style="height:1px;background:${BORDER};"></div></td></tr>
<tr><td style="padding:32px 40px 40px;font-family:${FONT_BODY};font-size:15px;line-height:1.65;color:${TEXT_BODY};">${bodyHtml}</td></tr>
</table>
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;margin-top:16px;"><tr><td style="font-family:${FONT_BODY};font-size:11px;color:${TEXT_FAINT};text-align:center;line-height:1.5;">
Este email foi enviado automaticamente pelo <a href="https://projetus.vercel.app" style="color:${BRAND};text-decoration:none;">Projetus</a>.<br>Se você não reconhece esta mensagem, pode ignorá-la com segurança.
</td></tr></table>
</td></tr></table></body></html>`
}

const heading = (t) => `<h1 style="margin:0 0 14px;font-family:${FONT_HEADING};font-size:22px;font-weight:600;color:${TEXT_DARK};letter-spacing:-0.3px;line-height:1.3;">${escapeHtml(t)}</h1>`
const paragraph = (h) => `<p style="margin:0 0 16px;font-family:${FONT_BODY};font-size:15px;line-height:1.65;color:${TEXT_BODY};">${h}</p>`
const muted = (h) => `<p style="margin:16px 0 0;font-family:${FONT_BODY};font-size:13px;line-height:1.55;color:${TEXT_MUTED};">${h}</p>`
const button = (href, label) => `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:28px 0 4px;"><tr><td style="background:${BRAND};border-radius:10px;"><a href="${escapeHtml(href)}" style="display:inline-block;padding:13px 26px;color:#ffffff;font-family:${FONT_BODY};font-weight:600;font-size:14px;text-decoration:none;letter-spacing:0.2px;border-radius:10px;">${escapeHtml(label)}</a></td></tr></table>`
const infoRow = (label, value) => `<div style="padding:12px 0;border-bottom:1px solid ${BORDER};"><div style="font-family:${FONT_BODY};font-size:11px;font-weight:500;color:${TEXT_FAINT};text-transform:uppercase;letter-spacing:0.8px;margin-bottom:4px;">${escapeHtml(label)}</div><div style="font-family:${FONT_BODY};font-size:15px;color:${TEXT_DARK};font-weight:500;">${escapeHtml(value)}</div></div>`
const passwordBox = (p) => `<div style="background:${BG_SUBTLE};border:1px solid ${BORDER};border-radius:10px;padding:18px 20px;margin:20px 0;text-align:center;"><div style="font-family:${FONT_BODY};font-size:11px;font-weight:500;color:${TEXT_FAINT};text-transform:uppercase;letter-spacing:1px;margin-bottom:10px;">Nova senha</div><div style="font-family:'SF Mono', Monaco, Consolas, 'Liberation Mono', monospace;font-size:20px;color:${TEXT_DARK};font-weight:600;letter-spacing:1px;">${escapeHtml(p)}</div></div>`
const statusChange = (oldS, newS) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:20px 0;"><tr><td width="44%" style="background:${BG_SUBTLE};border:1px solid ${BORDER};border-radius:10px;padding:14px 16px;vertical-align:top;"><div style="font-family:${FONT_BODY};font-size:10px;font-weight:500;color:${TEXT_FAINT};text-transform:uppercase;letter-spacing:0.8px;margin-bottom:6px;">Anterior</div><div style="font-family:${FONT_BODY};font-size:14px;color:${TEXT_MUTED};font-weight:500;">${escapeHtml(oldS)}</div></td><td width="12%" align="center" style="color:${BRAND};font-size:18px;font-weight:700;font-family:${FONT_HEADING};">→</td><td width="44%" style="background:rgba(0,114,247,0.08);border:1px solid rgba(0,114,247,0.2);border-radius:10px;padding:14px 16px;vertical-align:top;"><div style="font-family:${FONT_BODY};font-size:10px;font-weight:600;color:${BRAND};text-transform:uppercase;letter-spacing:0.8px;margin-bottom:6px;">Atual</div><div style="font-family:${FONT_BODY};font-size:14px;color:${TEXT_DARK};font-weight:600;">${escapeHtml(newS)}</div></td></tr></table>`
const propostaCard = (nr, titulo) => { const t = titulo ? `<div style="font-family:${FONT_BODY};font-size:13px;color:${TEXT_MUTED};margin-top:4px;line-height:1.5;">${escapeHtml(titulo)}</div>` : ''; return `<div style="background:${BG_SUBTLE};border:1px solid ${BORDER};border-radius:10px;padding:14px 18px;margin:16px 0;"><div style="font-family:${FONT_BODY};font-size:10px;font-weight:500;color:${TEXT_FAINT};text-transform:uppercase;letter-spacing:0.8px;margin-bottom:4px;">Proposta</div><div style="font-family:${FONT_HEADING};font-size:15px;font-weight:600;color:${TEXT_DARK};">${escapeHtml(nr)}</div>${t}</div>` }
const commentQuote = (author, snippet) => `<div style="background:${BG_SUBTLE};border-left:3px solid ${BRAND};border-radius:0 10px 10px 0;padding:14px 18px;margin:16px 0;"><div style="font-family:${FONT_BODY};font-size:11px;font-weight:600;color:${BRAND};margin-bottom:6px;">${escapeHtml(author)}</div><div style="font-family:${FONT_BODY};font-size:14px;color:${TEXT_DARK};line-height:1.6;white-space:pre-wrap;">${escapeHtml(snippet)}</div></div>`

function welcomeEmail({ nome, email, loginUrl }) {
  return { subject: '[PREVIEW FINAL] Projetus — Sua conta foi criada', html: baseLayout('Bem-vindo ao Projetus', `${heading(`Bem-vindo(a), ${nome.split(' ')[0]}`)}${paragraph(`Sua conta no <strong>Projetus</strong> foi criada. Você já pode acessar a plataforma.`)}<div style="margin:24px 0;">${infoRow('Email de acesso', email)}</div>${muted(`A senha foi definida pelo administrador e deve ter sido comunicada separadamente.`)}${button(loginUrl, 'Acessar o sistema')}`) }
}

function passwordResetEmail({ nome, newPassword, loginUrl }) {
  return { subject: '[PREVIEW FINAL] Projetus — Sua senha foi alterada', html: baseLayout('Senha alterada', `${heading('Senha alterada')}${paragraph(`Olá <strong>${escapeHtml(nome)}</strong>, sua senha no Projetus foi alterada por um administrador.`)}${passwordBox(newPassword)}${muted('Recomendamos fazer login e trocar para uma senha pessoal assim que possível.')}${button(loginUrl, 'Fazer login')}`) }
}

function commentNotificationEmail({ nome, commenterName, propostaNr, propostaTitulo, snippet, propostaUrl }) {
  return { subject: `[PREVIEW FINAL] Projetus — Novo comentário na proposta ${propostaNr}`, html: baseLayout('Novo comentário', `${heading('Novo comentário')}${paragraph(`Olá <strong>${escapeHtml(nome)}</strong>, <strong>${escapeHtml(commenterName)}</strong> comentou em uma proposta que você acompanha.`)}${propostaCard(propostaNr, propostaTitulo)}${commentQuote(commenterName, snippet)}${button(propostaUrl, 'Ver proposta')}`) }
}

function situacaoChangeEmail({ nome, propostaNr, propostaTitulo, oldStatus, newStatus, propostaUrl }) {
  return { subject: `[PREVIEW FINAL] Projetus — Situação atualizada (${propostaNr})`, html: baseLayout('Situação atualizada', `${heading('Situação atualizada')}${paragraph(`Olá <strong>${escapeHtml(nome)}</strong>, uma proposta que você acompanha mudou de situação.`)}${propostaCard(propostaNr, propostaTitulo)}${statusChange(oldStatus, newStatus)}${button(propostaUrl, 'Ver proposta')}`) }
}

function assignmentEmail({ nome, assigneeName, isAssignee, propostaNr, propostaTitulo, propostaUrl }) {
  const headline = isAssignee ? 'Você foi atribuído(a)' : 'Técnico atribuído'
  const lead = isAssignee ? `Olá <strong>${escapeHtml(nome)}</strong>, você foi atribuído(a) como técnico(a) responsável por uma proposta.` : `Olá <strong>${escapeHtml(nome)}</strong>, <strong>${escapeHtml(assigneeName)}</strong> foi atribuído(a) como técnico(a) responsável.`
  return { subject: `[PREVIEW FINAL] Projetus — Técnico atribuído (${propostaNr})`, html: baseLayout('Técnico atribuído', `${heading(headline)}${paragraph(lead)}${propostaCard(propostaNr, propostaTitulo)}<div style="margin:16px 0;">${infoRow('Técnico responsável', assigneeName)}</div>${button(propostaUrl, 'Ver proposta')}`) }
}

function participantAddedEmail({ nome, propostaNr, propostaTitulo, propostaUrl }) {
  return { subject: `[PREVIEW FINAL] Projetus — Você foi adicionado à proposta ${propostaNr}`, html: baseLayout('Novo participante', `${heading('Você foi adicionado(a)')}${paragraph(`Olá <strong>${escapeHtml(nome)}</strong>, você foi adicionado(a) como participante de uma proposta.`)}${propostaCard(propostaNr, propostaTitulo)}${muted('A partir de agora você receberá notificações sobre atualizações nessa proposta — novos comentários, mudanças de situação e atribuições.')}${button(propostaUrl, 'Ver proposta')}`) }
}

// ———————————————————————————————————————————————————————————————
// 3. Build the 6 previews
// ———————————————————————————————————————————————————————————————
const NOME = 'Paulo Loureiro'
const PROPOSTA_NR = '123456/2025'
const PROPOSTA_TITULO = 'Modernização de equipamentos — Hospital Regional de Goiânia'

const emails = [
  { label: '1/6 Welcome', ...welcomeEmail({ nome: NOME, email: recipient, loginUrl: LOGIN_URL }) },
  { label: '2/6 Password Reset', ...passwordResetEmail({ nome: NOME, newPassword: 'TempProj#2026', loginUrl: LOGIN_URL }) },
  { label: '3/6 Comment', ...commentNotificationEmail({ nome: NOME, commenterName: 'Wellington Silva', propostaNr: PROPOSTA_NR, propostaTitulo: PROPOSTA_TITULO, snippet: 'Pessoal, confirmei com o órgão superior hoje — podemos avançar com o ajuste técnico no escopo. Preciso que alguém atualize a planilha de valores até quinta.', propostaUrl: PROPOSTA_URL }) },
  { label: '4/6 Situacao Change', ...situacaoChangeEmail({ nome: NOME, propostaNr: PROPOSTA_NR, propostaTitulo: PROPOSTA_TITULO, oldStatus: 'Em Análise', newStatus: 'Aprovada', propostaUrl: PROPOSTA_URL }) },
  { label: '5/6 Assignment (assignee view)', ...assignmentEmail({ nome: NOME, assigneeName: NOME, isAssignee: true, propostaNr: PROPOSTA_NR, propostaTitulo: PROPOSTA_TITULO, propostaUrl: PROPOSTA_URL }) },
  { label: '6/6 Participant Added', ...participantAddedEmail({ nome: NOME, propostaNr: PROPOSTA_NR, propostaTitulo: PROPOSTA_TITULO, propostaUrl: PROPOSTA_URL }) },
]

// ———————————————————————————————————————————————————————————————
// 4. Send sequentially
// ———————————————————————————————————————————————————————————————
const resend = new Resend(apiKey)

for (const e of emails) {
  try {
    const res = await resend.emails.send({ from: FROM, to: recipient, subject: e.subject, html: e.html })
    if (res.error) {
      console.error(`❌ ${e.label}:`, res.error.message || res.error)
    } else {
      console.log(`✅ ${e.label} → ${recipient} (id: ${res.data?.id ?? 'n/a'})`)
    }
  } catch (err) {
    console.error(`❌ ${e.label} threw:`, err.message)
  }
  await new Promise(r => setTimeout(r, 400))
}

console.log('\nDone.')
